let onboardingStep=0;
const renderWorkspace=render;
render=function(){renderWorkspace();renderOnboarding()}
function renderOnboarding(){if(!state?.user)return;let node=$('#onboarding');if(!node){node=document.createElement('section');node.id='onboarding';node.className='onboarding';node.setAttribute('role','dialog');node.setAttribute('aria-modal','true');document.body.append(node)}if(state.user.onboardingCompleted){node.hidden=true;node.innerHTML='';return}const coach=state.user.role==='coach',flow=coach?[['Welcome to TopCoach 🎾','Everything you need to manage your tennis coaching in one place.'],['Run your coaching from one place','<ul><li>👥 Manage players & groups</li><li>📅 Schedule training sessions</li><li>💳 Track hours & payments</li></ul>'],['You’re ready to go 🚀','Create your first group and schedule your first training session.']]:[['Welcome to TopCoach 🎾','Find coaches, join training sessions and keep track of your tennis schedule.'],['Your tennis, all in one place','<ul><li>🎾 Find coaches</li><li>📅 Join available training sessions</li><li>🗓 Track your upcoming sessions</li></ul>'],['Ready to play? 🚀','Find a coach and join your first training session.']], [title,body]=flow[onboardingStep],final=onboardingStep===flow.length-1;node.hidden=false;node.innerHTML=html`<div class="onboarding-card"><span class="onboarding-mark">🎾</span><div class="onboarding-progress" aria-label="Step ${onboardingStep+1} of ${flow.length}">${flow.map((_,index)=>html`<i class="${index<=onboardingStep?'active':''}"></i>`).join('')}</div><h1>${title}</h1><div class="onboarding-copy">${body}</div>${final?html`<div class="onboarding-actions"><button class="primary" onclick="completeOnboarding('${coach?'group':'trainers'}')">${coach?'Create first group':'Find a coach'}</button><button onclick="completeOnboarding('home')">Explore TopCoach</button></div>`:html`<button class="primary onboarding-continue" onclick="onboardingNext()">Continue</button>`}</div>`}
function onboardingNext(){onboardingStep=Math.min(onboardingStep+1,2);renderOnboarding()}
async function completeOnboarding(destination){const button=$('#onboarding .primary');if(button)button.disabled=true;try{state=await api('/api/action',{action:'onboarding'});await loadLanguage(state.user.language||'en');onboardingStep=0;navigate(destination);if(destination==='group')setTimeout(newGroup,0)}catch(error){if(button)button.disabled=false;toast(error.message)}}
function sessionTimeRange(session){const [hours,minutes]=String(session.time||'00:00').split(':').map(Number),end=hours*60+minutes+(session.durationMinutes||Math.round((session.ends-session.begins)/60)||60);return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}–${String(Math.floor((end%1440)/60)).padStart(2,'0')}:${String(end%60).padStart(2,'0')}`}
function coachHomeText(key){const copy={en:{today:'Today’s sessions',requests:'Requests',none:'No new requests',newRequest:'new request',newRequests:'new requests',next:'Next',calendar:'View calendar →',emptyToday:'No sessions today',emptyFuture:'No upcoming sessions',plan:'Plan your next session in Calendar.',group:'Group',individual:'Individual',player:'player',players:'players',tomorrow:'Tomorrow',premium:'TopCoach Premium',premiumCopy:'Unlock more coaching tools →'},ru:{today:'Тренировки сегодня',requests:'Заявки',none:'Новых заявок нет',newRequest:'новая заявка',newRequests:'новых заявок',next:'Следующая',calendar:'Открыть календарь →',emptyToday:'Сегодня тренировок нет',emptyFuture:'Ближайших тренировок нет',plan:'Запланируйте тренировку в Календаре.',group:'Группа',individual:'Индивидуальная',player:'ученик',players:'ученика',tomorrow:'Завтра',premium:'TopCoach Premium',premiumCopy:'Больше инструментов для тренера →'},kaz:{today:'Бүгінгі жаттығулар',requests:'Өтінімдер',none:'Жаңа өтінімдер жоқ',newRequest:'жаңа өтінім',newRequests:'жаңа өтінім',next:'Келесі',calendar:'Күнтізбені ашу →',emptyToday:'Бүгін жаттығу жоқ',emptyFuture:'Алдағы жаттығулар жоқ',plan:'Жаттығуды Күнтізбеде жоспарлаңыз.',group:'Топ',individual:'Жеке',player:'ойыншы',players:'ойыншы',tomorrow:'Ертең',premium:'TopCoach Premium',premiumCopy:'Жаттықтырушыға көбірек құралдар →'}};return (copy[uiLanguage]||copy.en)[key]||copy.en[key]}
function coachHomeDate(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}
function coachNextLabel(date,today){const target=new Date(`${date}T12:00:00`),tomorrow=new Date(`${today}T12:00:00`);tomorrow.setDate(tomorrow.getDate()+1);if(date===`${tomorrow.getFullYear()}-${String(tomorrow.getMonth()+1).padStart(2,'0')}-${String(tomorrow.getDate()).padStart(2,'0')}`)return `${coachHomeText('tomorrow')} · ${target.toLocaleDateString(uiLanguage==='ru'?'ru-RU':uiLanguage==='kaz'?'kk-KZ':'en-US',{month:'short',day:'numeric'})}`;return target.toLocaleDateString(uiLanguage==='ru'?'ru-RU':uiLanguage==='kaz'?'kk-KZ':'en-US',{weekday:'long',month:'short',day:'numeric'})}
function coachHomeCard(session,caption=''){const group=state.groups.find(item=>item.id===session.group),groupSession=group?.type==='Групповая'||group?.type==='Group training',participants=session.members?.length||0,venue=String(session.place||'').split(' · ')[0],kind=groupSession?coachHomeText('group'):coachHomeText('individual'),participantText=participants===1?coachHomeText('player'):coachHomeText('players');return html`<button class="card coach-today-session ${sessionStatus(session)==='live'?'live':''}" onclick="openSession('${session.id}')"><span class="coach-session-info">${caption?html`<b class="session-caption">${e(caption)}</b>`:''}<strong>${e(session.name)}</strong><time>${sessionTimeRange(session)}</time><small>${kind}${groupSession?` · ${participants} ${participantText}`:''}</small>${venue?html`<em>📍 ${e(venue)}</em>`:''}</span><span aria-hidden="true">›</span></button>`}
function coachHomePremium(){return html`<button class="premium-banner compact-premium" onclick="navigate('premium')"><span><small>${coachHomeText('premium')}</small><strong>${coachHomeText('premiumCopy')}</strong></span><b aria-hidden="true">↗</b></button>`}
function coachGreeting(hour){const copy={en:['Good morning','Good afternoon','Good evening'],ru:['Доброе утро','Добрый день','Добрый вечер'],kaz:['Қайырлы таң','Қайырлы күн','Қайырлы кеш']}[uiLanguage]||['Good morning','Good afternoon','Good evening'];return copy[hour<12?0:hour<18?1:2]}
function coachHome(){const today=coachHomeDate(),todaySessions=state.sessions.filter(session=>session.date===today&&sessionStatus(session)!=='cancelled').sort((a,b)=>a.begins-b.begins),next=state.sessions.filter(session=>session.date>today&&sessionStatus(session)==='scheduled').sort((a,b)=>a.begins-b.begins)[0],pending=state.requests.filter(request=>request.status==='pending').length,firstName=(state.user.fullName||'Coach').trim().split(/\s+/)[0],requestText=pending?`${pending} ${pending===1?coachHomeText('newRequest'):coachHomeText('newRequests')}`:coachHomeText('none');return html`<section class="coach-home"><header class="coach-greeting"><strong>${coachGreeting(new Date().getHours())}, ${e(firstName)} 👋</strong></header><section class="home-section"><div class="section-title"><h2>${coachHomeText('today')}</h2><span class="count-badge">${todaySessions.length}</span></div>${todaySessions.map(session=>coachHomeCard(session)).join('')||html`<div class="card home-empty"><strong>${coachHomeText('emptyToday')}</strong>${next?html`<span>${e(next.name)} · ${sessionTimeRange(next)}</span>`:''}</div>`}</section><button class="card home-requests ${pending?'has-requests':''}" onclick="navigate('requests')"><span><small>${coachHomeText('requests')}</small><strong>${requestText}</strong></span><span aria-hidden="true">›</span></button><section class="home-section home-next"><div class="section-title"><h2>${coachHomeText('next')}</h2><button class="text-action" onclick="navigate('calendar')">${coachHomeText('calendar')}</button></div>${next?coachHomeCard(next,coachNextLabel(next.date,today)):html`<div class="card home-empty"><strong>${coachHomeText('emptyFuture')}</strong><span>${coachHomeText('plan')}</span></div>`}</section>${coachHomePremium()}</section>`}
