function studentView(){const id=Number(new URL(window.location.href).searchParams.get('studentId')),student=state.students.find(p=>p.telegramId===id);if(!student){navigate('groups');return ''}const groups=state.groups.filter(g=>g.members.includes(id)),sessions=state.sessions.filter(s=>s.members.includes(id)).sort((a,b)=>b.begins-a.begins),name=student.displayName||student.fullName;return heading(e(name))+html`<section class="student-profile"><div class="card student-profile-summary redesigned"><div class="avatar student-avatar">${e(name.slice(0,1))}</div><div><strong>${e(name)}</strong><span class="meta">${student.level?`Level ${e(student.level)}`:'Level not set'}</span></div><div class="student-balance"><strong>${balanceLabel(student.hours)}</strong><small>Remaining balance</small></div><div class="student-groups-summary">${groups.map(g=>html`<span class="badge">${e(g.name)}</span>`).join('')||'<span class="meta">No groups</span>'}</div></div><div class="student-primary-action"><button class="primary" onclick="payment(${id})">+ Hours & payment</button><button onclick="editStudent(${id})">Edit student</button><button class="icon-action" onclick="chat(${id})">✈</button></div><section class="student-detail-section"><div class="group-section-heading"><h2>Groups · ${groups.length}</h2><button class="text-action" onclick="editStudent(${id})">+ Add</button></div>${groups.map(g=>html`<button class="student-group-link" onclick="groupDetail('${g.id}')"><strong>${e(g.name)}</strong><small>${groupDays(g)} · ${e(g.time)} · ${g.durationMinutes||60} min</small><span>›</span></button>`).join('')||'<p class="meta">No groups yet.</p>'}</section><section class="student-detail-section"><div class="group-section-heading"><h2>Recent sessions</h2>${sessions.length>3?html`<button class="text-action" onclick="navigate('calendar')">View all sessions →</button>`:''}</div>${sessions.slice(0,3).map(s=>html`<button class="student-session-link" onclick="openSession('${s.id}')"><span>${formatDate(s.date)} · ${e(s.time)}</span><strong>${e(s.name)}</strong><small>${status(s)} ›</small></button>`).join('')||'<p class="meta">No sessions yet.</p>'}</section></section>`}
function editStudent(pid){const p=state.students.find(item=>item.telegramId===pid),chosen=new Set(state.groups.filter(g=>g.members.includes(pid)).map(g=>g.id)),levels=state.playerLevels||[];modal(html`<h2>Edit student</h2><form class="fields" novalidate><label>Display name<input name="name" value="${e(p.displayName||p.fullName)}" required></label><label>Level<select name="level"><option value="">Not set</option>${levels.map(level=>html`<option value="${level}" ${p.level===level?'selected':''}>Level ${level}</option>`).join('')}</select></label><fieldset><legend>Groups</legend>${state.groups.map(g=>html`<label class="check"><input type="checkbox" name="groups" value="${g.id}" ${chosen.has(g.id)?'checked':''}><span>${e(g.name)}</span></label>`).join('')}</fieldset><label>Comment<textarea name="comment">${e(p.comment||'')}</textarea></label><div class="actions"><button class="primary">Save changes</button><button type="button" onclick="closeDialog()">Cancel</button></div></form>`);$('#dialog form').onsubmit=async event=>{event.preventDefault();const f=event.target;if(!validateForm(f))return;const data=new FormData(f);await mutate('student_update',{player:pid,name:data.get('name'),level:data.get('level'),comment:data.get('comment'),groups:data.getAll('groups')})}}
